const { favoriteLayout } = options.getState();
const gridLayoutFavorites = options.getProps().favorites;
const currentLayout = gridLayoutFavorites[favoriteLayout];
const topWindow = aras.getMostTopWindowWithAras(window);
const confirmDialog = topWindow.ArasModules.Dialog.confirm;

const dialogMessage = aras.getResource('', 'delete_layout_dialog.message', currentLayout.label);
const okButtonText = aras.getResource('', 'confirm_delete.delete');
const title = aras.getResource('', 'delete_layout_dialog.title');
const result = await confirmDialog(dialogMessage, {
	title,
	image: '../images/Delete.svg',
	okButtonText,
	okButtonModifier: 'aras-button_secondary'
});

if (result !== 'ok') {
	return;
}

const { favorites } = aras.getMainWindow();
await favorites.delete(favoriteLayout);
const { setCurrentLayout } = options.getActions();
setCurrentLayout('searchview.commandbar.layouts.default');
